//! Perl 5.42 case mapping: `lc`, `uc`, `fc`, `ucfirst`, `lcfirst`.
//!
//! These use Unicode 16.0.0 *full* case mappings (`uc("ß") eq "SS"`,
//! `lc("İ") eq "i\x{307}"`, `ucfirst("ǆ") eq "ǅ"`, `fc("ẞ") eq "ss"`) with no
//! context sensitivity: perl does not apply the Final_Sigma rule
//! (`lc("ΣΑΣ") eq "σασ"`) nor any language-specific tailoring. Rust's
//! `str::to_lowercase` differs (it applies Final_Sigma and follows the
//! toolchain's Unicode version), so biber-facing code must use these.
//!
//! The tables are generated by asking the O3 perl for every code point
//! (`tools/oracle/probes/perl-compat/gen_unicode_tables.pl`); a test checks a
//! SHA-256 digest of the mapping of every code point against the oracle.
//!
//! biber call sites: `lc`/`fc` everywhere for case-insensitive comparison of
//! field, type and option names (`fc($a) eq fc($b)`, e.g. sourcemap
//! `per_type`, `map_matchesi`, `strip_nosort`), `lc` of `month` names
//! (`bibtex.pm:1987`), `uc`/`ucfirst` in label and initials generation
//! (`Utils.pm` `ucinit`, `Internals.pm` labelalpha `ifnames`/`uc` options),
//! and `uc` in `Text::Roman`/`Business::ISBN` input normalisation.

use crate::tables::case::{FOLD, LOWER, TITLE, UPPER};

#[inline]
fn lookup(table: &'static [(u32, &'static str)], c: char) -> Option<&'static str> {
    table.binary_search_by_key(&(c as u32), |e| e.0).ok().map(|i| table[i].1)
}

fn map_str(s: &str, table: &'static [(u32, &'static str)], ascii: fn(u8) -> u8) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if c.is_ascii() {
            out.push(ascii(c as u8) as char);
        } else {
            match lookup(table, c) {
                Some(m) => out.push_str(m),
                None => out.push(c),
            }
        }
    }
    out
}

/// Perl `lc`.
pub fn lc(s: &str) -> String {
    if s.bytes().all(|b| b.is_ascii() && !b.is_ascii_uppercase()) {
        return s.to_owned();
    }
    map_str(s, LOWER, |b| b.to_ascii_lowercase())
}

/// Perl `uc`.
pub fn uc(s: &str) -> String {
    map_str(s, UPPER, |b| b.to_ascii_uppercase())
}

/// Perl `fc` (full case folding, `CaseFolding.txt` status C+F).
pub fn fc(s: &str) -> String {
    if s.bytes().all(|b| b.is_ascii() && !b.is_ascii_uppercase()) {
        return s.to_owned();
    }
    map_str(s, FOLD, |b| b.to_ascii_lowercase())
}

/// `fc($a) eq fc($b)` without allocating in the common ASCII case.
pub fn fc_eq(a: &str, b: &str) -> bool {
    if a.is_ascii() && b.is_ascii() {
        return a.eq_ignore_ascii_case(b);
    }
    fc(a) == fc(b)
}

/// Non-identity `lc` mapping of a single character (`None` = unchanged).
pub fn lc_char(c: char) -> Option<&'static str> {
    lookup(LOWER, c)
}

/// Non-identity `uc` mapping of a single character (`None` = unchanged).
pub fn uc_char(c: char) -> Option<&'static str> {
    lookup(UPPER, c)
}

/// Non-identity `fc` mapping of a single character (`None` = unchanged).
pub fn fc_char(c: char) -> Option<&'static str> {
    lookup(FOLD, c)
}

/// Non-identity titlecase (`ucfirst`) mapping of a single character.
pub fn tc_char(c: char) -> Option<&'static str> {
    lookup(TITLE, c)
}

/// Perl `ucfirst`: titlecase (full mapping) of the first character.
pub fn ucfirst(s: &str) -> String {
    let mut it = s.chars();
    match it.next() {
        None => String::new(),
        Some(c) => {
            let mut out = String::with_capacity(s.len() + 2);
            match lookup(TITLE, c) {
                Some(m) => out.push_str(m),
                None => out.push(c),
            }
            out.push_str(it.as_str());
            out
        }
    }
}

/// Perl `lcfirst`: lowercase (full mapping) of the first character.
pub fn lcfirst(s: &str) -> String {
    let mut it = s.chars();
    match it.next() {
        None => String::new(),
        Some(c) => {
            let mut out = String::with_capacity(s.len() + 2);
            match lookup(LOWER, c) {
                Some(m) => out.push_str(m),
                None => out.push(c),
            }
            out.push_str(it.as_str());
            out
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basics() {
        assert_eq!(lc("ΣΑΣ"), "σασ");
        assert_eq!(uc("straße"), "STRASSE");
        assert_eq!(lc("İ"), "i\u{307}");
        assert_eq!(ucfirst("ǆa"), "ǅa");
        assert_eq!(ucfirst("ßa"), "Ssa");
        assert_eq!(fc("ẞ"), "ss");
        assert_eq!(lcfirst("ABC"), "aBC");
        assert!(fc_eq("STRASSE", "straße"));
        assert_eq!(uc_char('ß'), Some("SS"));
        assert_eq!(lc_char('A'), Some("a"));
        assert_eq!(lc_char('a'), None);
    }
}
